css:
.ds-signout { --ds-cover-bg: var(--ds-kraft); }
.ds-signout .ds-section h2, .ds-signout .ds-cover-name { font-family: var(--font-display); font-weight: 800; text-transform: uppercase; letter-spacing: -0.01em; }
.ds-signout .ds-section h2 { font-size: clamp(40px, 5.5vw, 72px); line-height: .9; }
.ds-signout .ds-eyebrow, .ds-signout .ds-chip { font-family: var(--font-display); font-weight: 700; letter-spacing: .1em; }
.ds-signout .ds-chip { border-radius: 0; border-width: 2px; }
.ds-signout .so-kraft { fill: var(--ds-kraft); } .ds-signout .so-haz rect, .ds-signout .so-haz-f { fill: var(--ds-hazard); } .ds-signout .so-haz-ink polygon { fill: var(--ds-ink); }
.ds-signout .so-cond { font-family: var(--font-display); font-weight: 800; font-size: 44px; fill: var(--ds-ink); } .ds-signout .so-cond-s { font-family: var(--font-display); font-weight: 700; font-size: 20px; fill: var(--ds-ink); }
.ds-signout .so-blk { font-family: var(--font-display); font-weight: 700; font-size: 11px; letter-spacing: .1em; fill: var(--ds-ink); } .ds-signout .so-muted-f { fill: var(--ds-ink-muted); } .ds-signout .so-on-pick { fill: var(--ds-on-vermilion); } .ds-signout .so-on-hatch { fill: var(--ds-ink); }
.ds-signout .so-rule2 { stroke: var(--ds-ink); stroke-width: 2; } .ds-signout .so-grid rect { fill: var(--ds-kraft-raised); stroke: var(--ds-ink); stroke-width: 1.5; } .ds-signout .so-cell-f { fill: var(--ds-kraft-raised); } .ds-signout .so-frame { fill: none; stroke: var(--ds-ink); stroke-width: 2; }
.ds-signout .so-hatch line { stroke: var(--ds-ink); stroke-width: 1.5; opacity: .55; } .ds-signout .so-pick { fill: var(--ds-vermilion); }
.ds-signout .so-stamp { fill: none; stroke: var(--ds-ink); stroke-width: 2.5; } .ds-signout .so-stamp-t { font-family: var(--font-display); font-weight: 800; font-size: 16px; letter-spacing: .1em; fill: var(--ds-ink); }
.ds-signout .so-muted { color: var(--ds-ink-muted); } .ds-signout .so-vermilion { color: var(--ds-vermilion); }
.ds-signout .so-btn { font-family: var(--font-display); font-size: 16px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; line-height: 18px; padding: 10px 16px; border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); color: var(--ds-ink); cursor: pointer; transition: background 100ms; }
.ds-signout .so-btn:hover { background: var(--ds-kraft-sunk); } .ds-signout .so-btn:focus-visible { outline: 2px solid var(--ds-vermilion); outline-offset: 2px; }
.ds-signout .so-btn-primary { background: var(--ds-vermilion); color: var(--ds-on-vermilion); border-color: var(--ds-ink); } .ds-signout .so-btn-primary:hover { background: var(--ds-vermilion); }
.ds-signout .so-btn-haz { background: var(--ds-hazard); color: var(--ds-ink); } .ds-signout .so-btn-haz:hover { background: var(--ds-hazard); }
.ds-signout .so-tag { display: inline-flex; padding: 3px 8px; border: 1px solid var(--ds-ink); font-family: var(--font-display); font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; background: var(--ds-kraft-raised); }
.ds-signout .so-tag-open { color: var(--ds-open); border-color: var(--ds-open); } .ds-signout .so-tag-pick { background: var(--ds-vermilion); color: var(--ds-on-vermilion); } .ds-signout .so-tag-taken { background: repeating-linear-gradient(45deg, var(--ds-kraft-raised) 0 5px, var(--ds-line) 5px 7px); color: var(--ds-ink-muted); }
.ds-signout .so-stamp-i { display: inline-flex; padding: 4px 10px; border: 2px solid var(--ds-ink); font-family: var(--font-display); font-size: 14px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; transform: rotate(-8deg); }
.ds-signout .so-stat { display: grid; gap: 4px; padding: 12px 16px; border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); min-width: 150px; } .ds-signout .so-stat-pick { background: var(--ds-vermilion); } .ds-signout .so-stat-pick .t-label, .ds-signout .so-stat-pick .so-small { color: var(--ds-on-vermilion); }
.ds-signout .so-of { font-size: 20px; color: var(--ds-ink-muted); } .ds-signout .so-small { font-family: var(--font-body); font-size: 12px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--ds-ink-muted); line-height: 1.4; } .ds-signout .ds-stats { gap: 16px; }
.ds-signout .so-note { padding: 12px 16px; border: 2px solid var(--ds-ink); font-size: 15px; line-height: 1.5; background: var(--ds-kraft-raised); } .ds-signout .so-note strong { font-family: var(--font-display); font-weight: 700; text-transform: uppercase; letter-spacing: .06em; }
.ds-signout .so-note-haz { border-top: 10px solid var(--ds-hazard); background: var(--ds-hazard-soft); } .ds-signout .so-note-open { background: var(--ds-open-soft); } .ds-signout .so-note-neg { background: var(--ds-negative-soft); }
.ds-signout .so-sheet { border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); } .ds-signout .so-sheet-haz { height: 10px; background: repeating-linear-gradient(-45deg, var(--ds-hazard) 0 12px, var(--ds-ink) 12px 24px); }
.ds-signout .so-sheet-body { padding: 20px 24px 16px; } .ds-signout .so-sheet h3 { margin: 6px 0 16px; } .ds-signout .so-sheet-foot { margin: 14px 0 0; }
.ds-signout .so-grid { display: grid; grid-template-columns: minmax(140px, 1.4fr) repeat(3, minmax(0, 1fr)); border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); margin-top: 24px; }
.ds-signout .so-cell { padding: 8px 8px; border-right: 1px solid var(--ds-line); border-bottom: 1px solid var(--ds-line); font-family: var(--font-display); font-weight: 700; font-size: 12px; letter-spacing: .04em; text-transform: uppercase; display: grid; gap: 2px; align-content: start; min-height: 58px; min-width: 0; overflow-wrap: normal; }
.ds-signout .so-row-h .t-display-m { font-size: 17px; line-height: 19px; }
@container (min-width: 760px) { .ds-signout .so-row-h .t-display-m { font-size: 28px; line-height: 28px; } }
@container (min-width: 760px) { .ds-signout .so-cell { padding: 10px 12px; font-size: 14px; letter-spacing: .06em; } }
.ds-signout .so-grid { grid-template-columns: minmax(96px, 1.4fr) repeat(3, minmax(0, 1fr)); }
.ds-signout .so-cell:nth-child(4n) { border-right: 0; } .ds-signout .so-head { background: var(--ds-kraft-sunk); font-size: 11px; letter-spacing: .1em; color: var(--ds-ink-muted); min-height: 0; }
.ds-signout .so-row-h { background: var(--ds-kraft-raised); } .ds-signout .so-row-h .t-display-m { text-transform: uppercase; }
.ds-signout .so-open { color: var(--ds-ink); } .ds-signout .so-open:hover { background: var(--ds-kraft-sunk); cursor: pointer; }
.ds-signout .so-pick { background: var(--ds-vermilion); color: var(--ds-on-vermilion); } .ds-signout .so-pick .so-small { color: var(--ds-on-vermilion); }
.ds-signout .so-taken { background: repeating-linear-gradient(45deg, var(--ds-kraft-raised) 0 6px, var(--ds-line) 6px 8px); color: var(--ds-ink-muted); }
.ds-signout .so-legend { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 12px; font-size: 13px; } .ds-signout .so-legend span { display: inline-flex; align-items: center; gap: 6px; } .ds-signout .so-leg { display: inline-block; width: 16px; height: 16px; border: 1px solid var(--ds-ink); } .ds-signout .so-leg-pick { background: var(--ds-vermilion); } .ds-signout .so-leg-taken { background: repeating-linear-gradient(45deg, var(--ds-kraft-raised) 0 3px, var(--ds-line) 3px 5px); }
.ds-signout .so-sample { background: var(--ds-kraft); padding: 0 20px 48px; border-bottom: 2px solid var(--ds-ink); } .ds-signout .so-sample-in { max-width: 1140px; margin: 0 auto; border: 2px solid var(--ds-ink); background: var(--ds-kraft); }
.ds-signout .so-sample-top { display: grid; gap: 16px; padding: 20px 24px; border-bottom: 2px solid var(--ds-ink); } .ds-signout .so-brand { font-size: clamp(48px, 7vw, 80px); line-height: .85; }
.ds-signout .so-meta-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; } .ds-signout .so-num-s { font-size: 18px; line-height: 22px; }
.ds-signout .so-steps { display: flex; border-bottom: 2px solid var(--ds-ink); } .ds-signout .so-step { flex: 1; padding: 8px 24px; font-family: var(--font-display); font-weight: 700; font-size: 13px; letter-spacing: .1em; text-transform: uppercase; color: var(--ds-ink-muted); border-right: 1px solid var(--ds-line); } .ds-signout .so-step-on { color: var(--ds-ink); box-shadow: inset 0 -4px 0 var(--ds-vermilion); }
.ds-signout .so-sample-grid { display: grid; gap: 24px; padding: 24px; } .ds-signout .so-sample-h { margin: 6px 0 0; } .ds-signout .so-sample-lede { margin-top: 12px; max-width: 52ch; }
.ds-signout .so-side { display: grid; gap: 16px; align-content: start; } .ds-signout .so-panel { border: 2px solid var(--ds-ink); background: var(--ds-kraft-raised); padding: 16px 18px; min-width: 0; } .ds-signout .so-panel-h { margin: 0 0 12px; }
.ds-signout .so-empty { border: 2px dashed var(--ds-line); padding: 16px; margin-bottom: 12px; } .ds-signout .so-empty p { margin: 0; } .ds-signout .so-empty .so-small { margin-top: 4px; }
.ds-signout .so-sample .so-sheet-foot { padding: 0 24px 20px; margin: 0; }
@container (min-width: 760px) { .ds-signout .so-sample { padding: 0 40px 64px; } .ds-signout .so-sample-top { grid-template-columns: auto 1fr; align-items: end; } .ds-signout .so-sample-grid { grid-template-columns: 3fr 2fr; } }

.ds-signout { --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-vermilion); --ds-hand-fill2: var(--ds-ink); --ds-hand-muted: var(--ds-kraft-sunk); --ds-hand-ground: var(--ds-kraft-raised); --ds-hand-stroke: 2; --ds-hand-cap: square; --ds-hand-tex: 1.5; --ds-hand-bg: var(--ds-kraft);
  --ds-tpl-edge: 2px solid var(--ds-ink); --ds-tpl-radius: 0; --ds-tpl-rule: 2px solid var(--ds-ink); --ds-tpl-tile-shadow: none; --ds-slide-bg: var(--ds-kraft-raised); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: var(--ds-vermilion); --ds-slide-title-fg: var(--ds-on-vermilion); --ds-slide-split-a: var(--ds-kraft-raised); --ds-slide-split-a-fg: var(--ds-ink); --ds-slide-split-b: var(--ds-vermilion); --ds-slide-split-b-fg: var(--ds-on-vermilion); --ds-hero-bg: var(--ds-kraft); --ds-tag-radius: 0; }
.ds-signout .h-text, .ds-signout .h-num { font-family: var(--font-display); font-weight: 700; } .ds-signout .h-text { letter-spacing: .1em; font-size: 11px; }
.ds-signout .h-tex-fill2 line { opacity: .55; }
.ds-signout .ds-tpl-tag { border: 1px solid var(--ds-ink); font-family: var(--font-display); font-weight: 700; letter-spacing: .1em; } .ds-signout .ds-tpl-tag.is-idle { background: var(--ds-kraft-sunk); color: var(--ds-ink-muted); }
.ds-signout .ds-tpl-split-a { border: 2px solid var(--ds-ink); } .ds-signout .ds-tpl-stage-title .ds-tpl-stage-foot { border-top-width: 2px; }
.ds-signout .ds-tpl-dropcap { font-family: var(--font-display); font-weight: 800; }
.ds-signout .so-stamp-i { animation: so-land 90ms ease-out both; }
@keyframes so-land { from { transform: rotate(-8deg) scale(1.15); } to { transform: rotate(-8deg) scale(1); } }
@media (prefers-reduced-motion: reduce) { .ds-signout .so-stamp-i { animation: none; } }
